        await authorize(tx, p, 'issuer', configurationId);
        sr2Assert(confirmed === true, 'Confirm revocation.');
      } else if (!['active', 'suspended'].includes(tx.tenant.state)) return null;
      await get(tx, 'configuration', configurationId);
